20	+/**
21	+ * @copyright
22	+ * Copyright 2025 Intel Corporation.
23	+ * SPDX-License-Identifier: Apache-2.0
24	+ *
25	+ * @test @b movbe_slf_sweep_sve
26	+ * @parblock
27	+ * Multi-width SLF sweep probe (SVE), extending movbe_dump_probe_c_sve
28	+ * (the hunt-v3 core-122 trigger recipe, kept untouched as evidence).
29	+ * Each thread keeps a private copy of the input, the bytes are reversed
30	+ * within each element by svtbl and stored BACK to the private copy's
31	+ * position, then immediately reloaded from there through svst1/svld1
32	+ * (the vector store->load-forwarding path), restored by a second svtbl
33	+ * (the index table is an involution) and compared bit-exact against the
34	+ * read-only golden buffer. Three improvements over the original probe:
35	+ * (A) multi-width — every pass sweeps three element widths (16-bit
36	+ * [1,0], 32-bit [3,2,1,0], 64-bit [7,6,5,4,3,2,1,0]) through the unified
37	+ * index formula (p/W)*W + (W-1-(p%W)); (B) VL-portable — all stack
38	+ * buffers are sized for the SVE architectural maximum VL of 2048 bits
39	+ * (256 bytes) and the walk uses svcntb() batches with svwhilelt tails,
40	+ * so the test is correct at ANY vector length (the original probe's
41	+ * [64] stack arrays overflow at VL>=1024); (C) no dead allocations —
42	+ * test->data holds only the golden buffer, cleanup frees everything it
43	+ * tracks. The init self-check permutes 50k random values per width
44	+ * through the same svtbl mechanism and compares bit-exact against
45	+ * __builtin_bswap16/32/64 (fail-closed, family precedent). Input is
46	+ * random (framework RNG at init), reused per iteration exactly as the
47	+ * family.
48	+ * @endparblock
49	+ */
50	+
51	+#include "sandstone.h"
52	+#include <cstdint>
53	+#include <cstdio>
54	+#include <cstring>
55	+
56	+#if defined(__aarch64__)
57	+#include <arm_sve.h>
58	+#include <sys/auxv.h>
59	+
60	+#ifndef HWCAP_SVE
61	+#define HWCAP_SVE (1 << 22)
62	+#endif
63	+#endif
64	+
65	+/* 64KB 扫描缓冲 (16384 u32, 按 u32 填充; 运行时按字节扫描 — 与元素宽度解耦) */
66	+#define SLF_SWEEP_BUFFER_BYTES (64 * 1024)
67	+/* SVE 架构最大 VL = 2048bit = 256 字节: 所有栈缓冲按此定容 (VL 可移植) */
68	+#define SVE_MAX_VECTOR_BYTES 256
69	+/* init 自检: 每种宽度的随机向量数 (家族 50k 验证先例) */
70	+#define SLF_SWEEP_SELFCHECK_VECS 50000
71	+
72	+struct movbe_slf_sweep_sve_data {
73	+    /* 改进 C: 唯一必要字段 — init 填充后只读的 golden 缓冲 */
74	+    uint8_t *golden;
75	+};
76	+
77	+#if defined(__aarch64__)
78	+/* 统一索引表: 元素宽 W 字节、字节位 p 的表项 = (p/W)*W + (W-1-(p%W))
79	+ * (元素内字节反转, 对合 — W=4 时即 probe-c 的 [3,2,1,0]) */
80	+static void slf_sweep_build_index_table(uint8_t *vidx_bytes, uint64_t vbytes, int width)
81	+{
82	+    for (uint64_t p = 0; p < vbytes; ++p)
83	+        vidx_bytes[p] = (uint8_t)((p / (uint64_t)width) * (uint64_t)width
84	+                                  + ((uint64_t)width - 1 - (p % (uint64_t)width)));
85	+}
86	+
87	+/* dump-on-failure + report_fail_msg (noreturn): index/width/golden/actual/xor + 字节分解 */
88	+static void slf_sweep_report_fail(uint64_t elem_index, uint64_t byte_offset, int width,
89	+                                  const uint8_t *golden, const uint8_t *actual)
90	+{
91	+    uint64_t golden_v = 0, actual_v = 0;
92	+    memcpy(&golden_v, golden, (size_t)width);
93	+    memcpy(&actual_v, actual, (size_t)width);
94	+    uint64_t xor_v = golden_v ^ actual_v;
95	+    char golden_hex[2 * 8 + 1], actual_hex[2 * 8 + 1], xor_hex[2 * 8 + 1];
96	+    for (int i = 0; i < width; ++i) {
97	+        /* MSB 先行 (家族 bytes[b3 b2 b1 b0] 约定) */
98	+        snprintf(golden_hex + 2 * i, 3, "%02X", golden[width - 1 - i]);
99	+        snprintf(actual_hex + 2 * i, 3, "%02X", actual[width - 1 - i]);
100	+        snprintf(xor_hex + 2 * i, 3, "%02X",
101	+                 (uint8_t)(golden[width - 1 - i] ^ actual[width - 1 - i]));
102	+    }
103	+    log_error("MovBE-SLF-sweep: round-trip failed at element %llu (byte offset %llu, "
104	+              "width %d): golden=0x%llX actual=0x%llX xor=0x%llX | bytes[b%d..b0] "
105	+              "golden=%s actual=%s xor=%s",
106	+              (unsigned long long)elem_index, (unsigned long long)byte_offset, width,
107	+              (unsigned long long)golden_v, (unsigned long long)actual_v,
108	+              (unsigned long long)xor_v, width - 1, golden_hex, actual_hex, xor_hex);
109	+    report_fail_msg("MovBE-SLF-sweep: round-trip failed at element %llu "
110	+                    "(byte offset %llu, width %d)",
111	+                    (unsigned long long)elem_index, (unsigned long long)byte_offset, width);
112	+}
113	+
114	+/* init 自检 (fail-closed): 每种宽度 N 个随机值过 svtbl 机制 (栈缓冲),
115	+ * 逐位对照 __builtin_bswap16/32/64 — 任一不符即 fail init (绝不静默 SUCCESS) */
116	+static void slf_sweep_selfcheck(int width)
117	+{
118	+    const uint64_t vbytes = (uint64_t)svcntb();
119	+    uint8_t vidx_bytes[SVE_MAX_VECTOR_BYTES];
120	+    slf_sweep_build_index_table(vidx_bytes, vbytes, width);
121	+    svbool_t pg_full = svwhilelt_b8((uint64_t)0, vbytes);
122	+    svuint8_t vidx = svld1_u8(pg_full, vidx_bytes);
123	+
124	+    uint8_t src[SVE_MAX_VECTOR_BYTES];
125	+    uint8_t dst[SVE_MAX_VECTOR_BYTES];
126	+    uint64_t checked = 0;
127	+    while (checked < SLF_SWEEP_SELFCHECK_VECS) {
128	+        uint64_t count = vbytes / (uint64_t)width;
129	+        if (count > (uint64_t)SLF_SWEEP_SELFCHECK_VECS - checked)
130	+            count = (uint64_t)SLF_SWEEP_SELFCHECK_VECS - checked;
131	+        uint64_t nbytes = count * (uint64_t)width;
132	+
133	+        for (uint64_t e = 0; e < count; ++e) {
134	+            if (width == 2) {
135	+                uint16_t v = (uint16_t)random32();
136	+                memcpy(src + e * 2, &v, 2);
137	+            } else if (width == 4) {
138	+                uint32_t v = random32();
139	+                memcpy(src + e * 4, &v, 4);
140	+            } else {
141	+                uint64_t v = random64();
142	+                memcpy(src + e * 8, &v, 8);
143	+            }
144	+        }
145	+
146	+        svbool_t pg = svwhilelt_b8((uint64_t)0, nbytes);
147	+        svuint8_t permuted = svtbl_u8(svld1_u8(pg, src), vidx);
148	+        svst1_u8(pg, dst, permuted);
149	+
150	+        for (uint64_t e = 0; e < count; ++e) {
151	+            uint8_t expected[8];
152	+            if (width == 2) {
153	+                uint16_t v, x;
154	+                memcpy(&v, src + e * 2, 2);
155	+                x = __builtin_bswap16(v);
156	+                memcpy(expected, &x, 2);
157	+            } else if (width == 4) {
158	+                uint32_t v, x;
159	+                memcpy(&v, src + e * 4, 4);
160	+                x = __builtin_bswap32(v);
161	+                memcpy(expected, &x, 4);
162	+            } else {
163	+                uint64_t v, x;
164	+                memcpy(&v, src + e * 8, 8);
165	+                x = __builtin_bswap64(v);
166	+                memcpy(expected, &x, 8);
167	+            }
168	+            if (memcmp(dst + e * (uint64_t)width, expected, (size_t)width) != 0) {
169	+                log_error("MovBE-SLF-sweep: init self-check failed at width %d, "
170	+                          "vector %llu: svtbl permutation != __builtin_bswap%d",
171	+                          width, (unsigned long long)(checked + e), width * 8);
172	+                report_fail_msg("movbe_slf_sweep_sve: init self-check failed "
173	+                                "(width %d, vector %llu)", width,
174	+                                (unsigned long long)(checked + e));
175	+            }
176	+        }
177	+        checked += count;
178	+    }
179	+}
180	+#endif
181	+
182	+static int movbe_slf_sweep_sve_init(struct test *test)
183	+{
184	+#if defined(__aarch64__)
185	+    unsigned long hwcap = getauxval(AT_HWCAP);
186	+    if ((hwcap & HWCAP_SVE) == 0) {
187	+        log_skip(CpuNotSupportedSkipCategory,
188	+                 "to be implemented (placeholder): ARM SVE required for movbe_slf_sweep_sve");
189	+        return EXIT_SKIP;
190	+    }
191	+#endif
192	+    auto *data = (movbe_slf_sweep_sve_data *)malloc(sizeof(movbe_slf_sweep_sve_data));
193	+    data->golden = (uint8_t *)aligned_alloc_safe(64, SLF_SWEEP_BUFFER_BYTES);
194	+
195	+    /* 64KB 按 u32 填充随机值; 运行时按字节扫描, 三种宽度共用同一 golden */
196	+    uint32_t *fill = (uint32_t *)data->golden;
197	+    for (size_t i = 0; i < SLF_SWEEP_BUFFER_BYTES / sizeof(uint32_t); ++i)
198	+        fill[i] = random32();
199	+
200	+#if defined(__aarch64__)
201	+    /* init 自检: 16/32/64-bit 三种宽度 (改进 A 的机制正确性) */
202	+    slf_sweep_selfcheck(2);
203	+    slf_sweep_selfcheck(4);
204	+    slf_sweep_selfcheck(8);
205	+#endif
206	+
207	+    test->data = data;
208	+    return EXIT_SUCCESS;
209	+}
210	+
211	+#if defined(__aarch64__)
212	+static int movbe_slf_sweep_sve_run(struct test *test, int cpu)
213	+{
214	+    (void)cpu;
215	+    auto *data = (movbe_slf_sweep_sve_data *)test->data;
216	+
217	+    const uint64_t total = SLF_SWEEP_BUFFER_BYTES;
218	+    const uint64_t vbytes = (uint64_t)svcntb();
219	+    /* SVE 架构保证 VL 是 128bit 的倍数 → vbytes 是 16 的倍数 → 对 W∈{2,4,8}
220	+     * 每批 (含 svwhilelt 尾批) 恒元素对齐; 索引表 256 字节定容封死 VL≥1024 溢出 */
221	+
222	+    /* 每线程私有副本 (SLF 探针, 消除多写者竞争; 同 probe-c。fork 模型下
223	+     * 随子进程退出回收, cleanup 只释放 test->data 所辖分配 — 同家族约定) */
224	+    static thread_local uint8_t *priv = nullptr;
225	+    if (!priv)
226	+        priv = (uint8_t *)aligned_alloc(64, SLF_SWEEP_BUFFER_BYTES);
227	+
228	+    /* 三种宽度的索引表, 每 run-call 建一次 (svuint8_t 是 sizeless 类型,
229	+     * 不能作数组元素, 故向量本体在宽度循环内从表中加载) */
230	+    static const int widths[3] = {2, 4, 8};
231	+    uint8_t vidx_bytes[3][SVE_MAX_VECTOR_BYTES];
232	+    for (int w = 0; w < 3; ++w)
233	+        slf_sweep_build_index_table(vidx_bytes[w], vbytes, widths[w]);
234	+    svbool_t pg_idx = svwhilelt_b8((uint64_t)0, vbytes);
235	+
236	+    TEST_LOOP(test, 1 << 13) {
237	+        /* 改进 A: 每遍在 16/32/64-bit 三种元素宽度间轮换扫描 */
238	+        for (int w = 0; w < 3; ++w) {
239	+            const int width = widths[w];
240	+            svuint8_t vidx = svld1_u8(pg_idx, vidx_bytes[w]);
241	+
242	+            /* 每遍宽度扫描前重置私有副本 (store-back 污染; 同 probe-c) */
243	+            memcpy(priv, data->golden, total);
244	+
245	+            for (uint64_t base = 0; base < total; base += vbytes) {
246	+                uint64_t n = (total - base < vbytes) ? total - base : vbytes;
247	+                svbool_t pg = svwhilelt_b8((uint64_t)0, n);
248	+
249	+                /* 载入本批字节 (向量) → 元素内字节重排 */
250	+                svuint8_t vswapped = svtbl_u8(svld1_u8(pg, priv + base), vidx);
251	+
252	+                /* ★ SLF 核心: 交换结果存回同一地址 (svst1 直打堆无栈中转) */
253	+                svst1_u8(pg, priv + base, vswapped);
254	+                __asm__ volatile("" ::: "memory");
255	+                /* ★ 立即重读同一地址 (真实 store→load 转发)。asm memory barrier
256	+                 * 阻断编译器消除真实 reload (无屏障时破坏 SLF 语义, 同 probe-c) */
257	+                svuint8_t reloaded = svld1_u8(pg, (const uint8_t *)priv + base);
258	+
259	+                /* 再交换一次还原 (同一索引表, svtbl 对合) → 栈 scratch */
260	+                svuint8_t vrestored = svtbl_u8(reloaded, vidx);
261	+                uint8_t out_bytes[SVE_MAX_VECTOR_BYTES];
262	+                svst1_u8(pg, out_bytes, vrestored);
263	+
264	+                /* 校验: 还原字节 == golden 字节 (按字节, 与宽度解耦);
265	+                 * ONLY on failure: dump index/width/golden/actual/xor + 字节分解 */
266	+                for (uint64_t i = 0; i < n; ++i) {
267	+                    if (out_bytes[i] != data->golden[base + i]) {
268	+                        uint64_t elem_off = (i / (uint64_t)width) * (uint64_t)width;
269	+                        slf_sweep_report_fail((base + elem_off) / (uint64_t)width,
270	+                                              base + elem_off, width,
271	+                                              data->golden + base + elem_off,
272	+                                              out_bytes + elem_off);
273	+                    }
274	+                }
275	+            }
276	+        }
277	+    }
278	+
279	+    return EXIT_SUCCESS;
280	+}
281	+#else
282	+static int movbe_slf_sweep_sve_run(struct test *test, int cpu)
283	+{
284	+    (void)test; (void)cpu;
285	+    log_skip(CpuNotSupportedSkipCategory,
286	+             "to be implemented (placeholder): ARM SVE required for movbe_slf_sweep_sve");
287	+    return EXIT_SKIP;
288	+}
289	+#endif
