307	+    .test_init = movbe_slf_sweep_sve_init,
308	+    .test_run = movbe_slf_sweep_sve_run,
309	+    .test_cleanup = movbe_slf_sweep_sve_cleanup,
310	+    .quality_level = TEST_QUALITY_PROD,
