         # dc-civac preserved and the 16B forward vectorized; MMU alias/split
diff --git a/tests/cpu/sve/vector2/insert_extract_sve.cpp b/tests/cpu/sve/vector2/insert_extract_sve.cpp
index 365bcce4..e47035ff 100644
--- a/tests/cpu/sve/vector2/insert_extract_sve.cpp
+++ b/tests/cpu/sve/vector2/insert_extract_sve.cpp
@@ -2,132 +2,116 @@
  * @copyright
  * Copyright 2025 Intel Corporation.
  * SPDX-License-Identifier: Apache-2.0
  *
  * @test @b insert_extract_sve
  * @parblock
  * SVE port of insert_extract: random lane insert + extract round-trip on
  * an SVE vector. Insert = predicate-gated single-lane write (svsel with a
  * single-lane predicate); extract = svlastb on the shifted vector or a
