208	
209	    /* 三种宽度的索引表, 每 run-call 建一次 (svuint8_t 是 sizeless 类型,
210	     * 不能作数组元素, 故向量本体在宽度循环内从表中加载) */
211	    static const int widths[3] = {2, 4, 8};
