213	    for (int w = 0; w < 3; ++w)
214	        slf_sweep_build_index_table(vidx_bytes[w], vbytes, widths[w]);
215	    svbool_t pg_idx = svwhilelt_b8((uint64_t)0, vbytes);
216	
217	    TEST_LOOP(test, 1 << 13) {
218	        /* 改进 A: 每遍在 16/32/64-bit 三种元素宽度间轮换扫描 */
219	        for (int w = 0; w < 3; ++w) {
220	            const int width = widths[w];
221	            svuint8_t vidx = svld1_u8(pg_idx, vidx_bytes[w]);
222	
223	            /* 每遍宽度扫描前重置私有副本 (store-back 污染; 同 probe-c) */
224	            memcpy(priv, data->golden, total);
225	
226	            for (uint64_t base = 0; base < total; base += vbytes) {
227	                uint64_t n = (total - base < vbytes) ? total - base : vbytes;
228	                svbool_t pg = svwhilelt_b8((uint64_t)0, n);
229	
230	                /* 载入本批字节 (向量) → 元素内字节重排 */
231	                svuint8_t vswapped = svtbl_u8(svld1_u8(pg, priv + base), vidx);
232	
233	                /* ★ SLF 核心: 交换结果存回同一地址 (svst1 直打堆无栈中转) */
234	                svst1_u8(pg, priv + base, vswapped);
235	                __asm__ volatile("" ::: "memory");
236	                /* ★ 立即重读同一地址 (真实 store→load 转发)。asm memory barrier
237	                 * 阻断编译器消除真实 reload (无屏障时破坏 SLF 语义, 同 probe-c) */
238	                svuint8_t reloaded = svld1_u8(pg, (const uint8_t *)priv + base);
239	
240	                /* 再交换一次还原 (同一索引表, svtbl 对合) → 栈 scratch */
241	                svuint8_t vrestored = svtbl_u8(reloaded, vidx);
242	                uint8_t out_bytes[SVE_MAX_VECTOR_BYTES];
243	                svst1_u8(pg, out_bytes, vrestored);
244	
245	                /* 校验: 还原字节 == golden 字节 (按字节, 与宽度解耦);
246	                 * ONLY on failure: dump index/width/golden/actual/xor + 字节分解 */
247	                for (uint64_t i = 0; i < n; ++i) {
248	                    if (out_bytes[i] != data->golden[base + i]) {
249	                        uint64_t elem_off = (i / (uint64_t)width) * (uint64_t)width;
250	                        slf_sweep_report_fail((base + elem_off) / (uint64_t)width,
251	                                              base + elem_off, width,
252	                                              data->golden + base + elem_off,
253	                                              out_bytes + elem_off);
254	                    }
255	                }
256	            }
257	        }
258	    }
259	
260	    return EXIT_SUCCESS;
261	}
